package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	s := string(data)
	first := s
	rest := ""
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		first = s[:i]
		rest = s[i+1:]
	}
	k, _ := strconv.Atoi(strings.TrimSpace(first))
	cnt := map[string]int{}
	start := -1
	for i := 0; i <= len(rest); i++ {
		alnum := false
		if i < len(rest) {
			c := rest[i]
			alnum = c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9'
		}
		if alnum {
			if start < 0 {
				start = i
			}
		} else if start >= 0 {
			cnt[strings.ToLower(rest[start:i])]++
			start = -1
		}
	}
	words := make([]string, 0, len(cnt))
	for w := range cnt {
		words = append(words, w)
	}
	sort.Slice(words, func(a, b int) bool {
		if cnt[words[a]] != cnt[words[b]] {
			return cnt[words[a]] > cnt[words[b]]
		}
		return words[a] < words[b]
	})
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for i := 0; i < len(words) && i < k; i++ {
		fmt.Fprintf(out, "%s %d\n", words[i], cnt[words[i]])
	}
}

